"use strict";
const $=id=>document.getElementById(id);
async function api(body){const response=await fetch('/api/foundation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw new Error(result.errors.join('; '));return result;}
function show(id,status,text){const box=$(id);box.replaceChildren();const label=document.createElement('span');label.className='status';label.textContent=status;box.append(label,document.createTextNode(text));}
function bind(id,fn){$(id).addEventListener('submit',async event=>{event.preventDefault();try{await fn(new FormData(event.target));}catch(error){show(id+'-result','ERR',error.message);}});}
const number=x=>Number(x).toLocaleString('sv-SE',{maximumSignificantDigits:10});
bind('derive',async f=>{const r=await api({operation:'derive',source:'frequency',target:f.get('target'),value:Number(f.get('value')),unit:'Hz',method:f.get('method')});$('trace').replaceChildren();show('derive-result',r.status,r.output?`${number(r.output.value)} ${r.output.unit}. Mass­ekvivalent betyder energins massa, inte automatiskt partikelns vilomassa.`:r.stop_reason+' · '+r.next_observation);for(const step of r.trace||[]){const li=document.createElement('li');li.textContent=`${step.status} · ${step.equation} · ${number(step.input)} ${step.input_unit} → ${number(step.output)} ${step.output_unit}`;$('trace').append(li);}});
bind('rf',async f=>{const r=await api({operation:'rf',frequency_Hz:Number(f.get('frequency')),distance_m:Number(f.get('distance'))});show('rf-result',r.status,`λ = ${number(r.wavelength_m)} m · FSPL = ${number(r.fspl_dB)} dB. Frekvenser: ${r.sidebands.map(s=>number(s.frequency_Hz)+' Hz').join(' / ')}.`);});
function element(name,attributes){const e=document.createElementNS('http://www.w3.org/2000/svg',name);for(const [k,v] of Object.entries(attributes))e.setAttribute(k,String(v));return e;}
function smith(gamma){const plot=$('smith');plot.replaceChildren();plot.append(element('circle',{cx:200,cy:200,r:175,fill:'none',stroke:'#a4c8d4','stroke-width':2}));plot.append(element('path',{d:'M25 200H375 M200 25V375',stroke:'#567580','stroke-dasharray':'5 5'}));for(const resistance of [.2,.5,1,2,5]){plot.append(element('circle',{cx:200+175*resistance/(1+resistance),cy:200,r:175/(1+resistance),fill:'none',stroke:'#37545f'}));}const x=200+175*gamma.real,y=200-175*gamma.imag;plot.append(element('path',{d:`M${x-7} ${y-7}L${x+7} ${y+7} M${x-7} ${y+7}L${x+7} ${y-7}`,stroke:'#ffe59e','stroke-width':4}));}
bind('stub',async f=>{const lossy=f.get('model')==='lossy';const r=await api({operation:'stub',alpha:Number(f.get('alpha')),load_Y_S:{real:Number(f.get('load')),imag:0},model:lossy?{q:100,connector_r_ohm:.1,junction_c_f:1e-13}:{},phase_rad:lossy?.03:0});smith(r.Gamma);show('stub-result',r.status,`|Γ| = ${number(r.magnitude)} · VSWR = ${r.VSWR===null?'ej ändlig passiv VSWR':number(r.VSWR)} · fas = ${number(r.phase_rad)} rad. Modellresultat, inte uppmätt S11.`);});
$('alpha').addEventListener('input',event=>{$('alpha-label').textContent=Number(event.target.value).toFixed(2);});
$('analog-run').addEventListener('click',async()=>{try{const r=await api({operation:'analog_demo'});show('analog-result',r.status,`${r.verdict} · största provavvikelse ${number(Math.max(...r.residuals))}. Fasförskjutet kontrollfall: ${r.phase_misfit_control.verdict}. Analog funktion bevaras.`);const plot=$('analog-plot');plot.replaceChildren();const points=[];for(let i=0;i<=256;i++)points.push(`${20+560*i/256},${85-60*Math.cos(2*Math.PI*i/256)}`);plot.append(element('polyline',{points:points.join(' '),stroke:'#a2ead5',fill:'none','stroke-width':2}));r.digital.forEach((v,i)=>plot.append(element('circle',{cx:20+560*i/(r.digital.length-1),cy:85-60*v.real,r:3,fill:'#ffe59e'})));}catch(e){show('analog-result','ERR',e.message);}});
$('geo-run').addEventListener('click',async()=>{try{const r=await api({operation:'multilayer_template'});const box=$('geo-result');box.replaceChildren();const symbols={natural_water:'≈≈≈',water_supply:'═══',sewer:'- - -',electricity:'ϟ ϟ ϟ',district_heating:'║ ║',fiber:'·····',RF:')))',transport:'━━━',topography:'≋≋≋'};for(const layer of r.layers){const item=document.createElement('div');item.className='layer';const symbol=document.createElement('span');symbol.className='swatch';symbol.textContent=symbols[layer];item.append(symbol,document.createTextNode(layer));const description=document.createElement('small');const nodes=r.nodes.filter(n=>n.layer===layer);description.textContent=nodes.length?nodes.map(n=>`${n.label} [${n.status}; ${n.lifecycle}]`).join(' · '):'STOP · inga källbundna objekt eller geometrier inlästa';item.append(description);for(const node of nodes){for(const source of node.provenance.filter(p=>p.startsWith('https://'))){const link=document.createElement('a');link.textContent=' Källa';link.href=source;link.style.color='#a2ead5';item.append(link);}}box.append(item);}}catch(e){show('geo-result','ERR',e.message);}});
bind('triangle',async f=>{const g=Number(f.get('generation'));const r=await api({operation:'triangle',generation:g,selected:g===4?[41,42]:[]});show('triangle-result',r.status,`${r.triangles} trianglar · kumulativt ${r.cumulative} · nivåer ${r.levels.join('–')}${r.selected.length?' · valda '+r.selected.join(', '):''}. STOP topologi: ${r.topology.stop_reason}.`);});
smith({real:0,imag:0});
